73	/** Prizes the KOing player takes for this Pokémon (§8.1). SHOULD be 2 for an
74	    ex/V/GX rule box and 3 for VMAX — every KO is worth 1 until the prize-count
75	    change is worth its blast radius (it ripples through the win condition and
76	    almost every KO test). `pokemonSuffixOf` below now supplies the exact
77	    classification this wants, read off the same persisted datum, so this is a
78	    one-line change (`pokemonSuffixOf(card) === null ? 1 : …`) when we take it. */
79	export function prizeValueOf(_card: Card): number {
80	  return 1;
