83	/** The printed rule-box SUFFIX of a Pokémon — the "V" / "VMAX" / "VSTAR" /
84	    "ex" / "GX" marker following the species name — or null for a plain Pokémon
85	    or a non-Pokémon. tcgdex drops its dedicated `suffix` field at ingest, but
86	    the marker is ALSO part of the card NAME (a Pokémon V is literally printed
87	    "<Species> V"), and the name IS persisted — so the datum survives, encoded
88	    in `name` rather than a lost column. Read LITERALLY: "V" does not match
89	    "VMAX"/"VSTAR" (each is its own suffix, none a space-then-"V"), which is
90	    exactly the distinction Choice Belt draws — "…Active Pokémon V" boosts a V,
91	    never a VMAX. The current SV-era catalog holds no V/VMAX/VSTAR at all, so
92	    Choice Belt's gate is dormant against the live pool and fires only once a
93	    prior-era set is ingested; it is correct in both cases. */
94	export type PokemonSuffix = "ex" | "V" | "VMAX" | "VSTAR" | "GX";
95	export function pokemonSuffixOf(card: Card): PokemonSuffix | null {
96	  if (card.category !== "Pokemon") return null;
97	  const { name } = card;
98	  if (name.endsWith(" VMAX")) return "VMAX";
99	  if (name.endsWith(" VSTAR")) return "VSTAR";
100	  if (name.endsWith(" V")) return "V";
101	  if (name.endsWith(" ex")) return "ex";
102	  if (name.endsWith(" GX")) return "GX";
103	  return null;
104	}
105	
106	/** What one attached Energy card provides toward a cost (§6.3). Catalog
107	    basic energies carry no `types` — the NAME is the datum, and real prints
108	    spell it both ways: "Fire Energy" and "Basic Darkness Energy"
109	    (sv06.5-098). The vocabulary is the shared BASIC_ENERGY_TYPES (§6.1,
110	    @luminous/schema) — INGEST DEBT: provision should become Card data at
111	    ingest; until then the name parse lives here. Anything unparseable
112	    (a special energy's fancy name) conservatively provides 1 Colorless: it can
113	    pay colorless slots, never typed ones (§6.4). This is the FALLBACK for an
114	    UNAUTHORED special energy — an authored one provides through its registry
115	    EnergyProgram instead (continuous.ts providedEnergy). */
116	export function energyProvidesOf(card: Card): string {
117	  const named = /^(?:Basic )?(.+) Energy$/.exec(card.name)?.[1];
118	  if (
119	    card.energyType === "Normal" &&
120	    named !== undefined &&
121	    (BASIC_ENERGY_TYPES as readonly string[]).includes(named)
122	  ) {
123	    return named;
124	  }
125	  return "Colorless";
126	}
