41	export function passivesOf(
42	  state: GameState,
43	  pokemon: InPlayPokemon,
44	): {
45	  damageReductionAfterWR: number;
46	  damageBonusBeforeWR: number;
47	  /** Pre-W/R bonuses gated on a board condition (Defiance Band), collected RAW
48	      and UNEVALUATED: the condition is seat-relative and this aggregation has no
49	      seat, so the two pre-W/R read sites fold them via `conditionHolds`
50	      (interpreter.ts `attackerPreWRBonus`). Kept out of `damageBonusBeforeWR` so
51	      the defender-reduction / HP reads, which never look at either, can't be
52	      accidentally credited an attacker's conditional bonus. */
53	  conditionalDamageBonusBeforeWR: { amount: number; cond: BoardCondition }[];
54	  /** Pre-W/R bonuses gated on the DEFENDER's rule-box suffix (Choice Belt),
55	      collected RAW like the board-condition list above: the defender is not a
56	      seat and this aggregation has none, so the read sites fold them via
57	      `pokemonSuffixOf(defenderCard)` in `attackerPreWRBonus`. */
58	  targetConditionalDamageBonusBeforeWR: { amount: number; targetSuffix: PokemonSuffix }[];
59	  hpBonus: number;
60	} {
61	  const top = topCardOf(state, pokemon);
62	  const sources: (PassiveEffects | undefined)[] = [
63	    top === undefined ? undefined : programFor(top.id)?.passive,
64	    ...pokemon.tools.map((uid) => {
65	      const id = state.cardIdByUid[uid];
66	      return id === undefined ? undefined : programFor(id)?.passive;
67	    }),
68	  ];
69	  const isBasic = top !== undefined && isBasicPokemon(top);
70	  let damageReductionAfterWR = 0;
71	  let damageBonusBeforeWR = 0;
72	  let hpBonus = 0;
73	  const conditionalDamageBonusBeforeWR: { amount: number; cond: BoardCondition }[] = [];
74	  const targetConditionalDamageBonusBeforeWR: {
75	    amount: number;
76	    targetSuffix: PokemonSuffix;
77	  }[] = [];
78	  for (const passive of sources) {
79	    if (passive === undefined) continue;
80	    damageReductionAfterWR += passive.damageReductionAfterWR ?? 0;
81	    damageBonusBeforeWR += passive.damageBonusBeforeWR ?? 0;
82	    if (passive.damageBonusBeforeWRIf !== undefined)
83	      conditionalDamageBonusBeforeWR.push(passive.damageBonusBeforeWRIf);
84	    if (passive.damageBonusBeforeWRIfTarget !== undefined)
85	      targetConditionalDamageBonusBeforeWR.push(passive.damageBonusBeforeWRIfTarget);
86	    if (isBasic) hpBonus += passive.basicHpBonus ?? 0;
87	  }
88	  return {
89	    damageReductionAfterWR,
90	    damageBonusBeforeWR,
91	    conditionalDamageBonusBeforeWR,
92	    targetConditionalDamageBonusBeforeWR,
93	    hpBonus,
94	  };
95	}
