97	/** §8.1 max HP as the KO check and the HUD must read it: the printed hp plus
98	    any continuous bonus (Bravery Charm). A null printed hp is the catalog
99	    data gap (cards.ts hpOf) and STAYS null — a bonus on top of unknown HP is
100	    still unknown, and a data gap never KOs. */
101	export function effectiveMaxHp(state: GameState, pokemon: InPlayPokemon): number | null {
102	  const top = topCardOf(state, pokemon);
103	  const hp = top === undefined ? null : hpOf(top);
104	  if (hp === null) return hp;
105	  const { hpBonus } = passivesOf(state, pokemon);
106	  return hp + hpBonus;
107	}
