109	/** §6.3/§6.4 — the flat list of energy UNITS a Pokémon's attached energies
110	    provide toward attack costs, evaluated per energy under its rules text:
111	    - a basic energy provides its one type (cards.ts energyProvidesOf);
112	    - an AUTHORED special energy provides its EnergyProgram's units (a concrete
113	      type, or ANY_ENERGY for a wildcard, and multi-unit is allowed — Double
114	      Turbo-likes), with Luminous's "{C} instead if another Special Energy is
115	      attached" evaluated against the holder's OTHER energies;
116	    - an UNAUTHORED special energy falls back to one Colorless (energyProvidesOf),
117	      so it stays playable rather than rejecting.
118	    The one provision read site: attack.ts's §8.2 cost check and the HUD's
119	    payability preview both call it, so they cannot drift (the D18 duplication
120	    is gone). costMet (attack.ts) consumes this flat list. */
121	export function providedEnergy(state: GameState, pokemon: InPlayPokemon): string[] {
122	  // Which attached energies are Special — for Luminous's "any OTHER Special
123	  // Energy attached" condition. Resolved once against the live board, then
124	  // shared by every unit lookup below (the condition is about the HOLDER, so it
125	  // is the same question for all of them).
126	  const specialUids = specialEnergyUids(state, pokemon);
127	  return pokemon.energy.flatMap((uid) => unitsOf(state, uid, specialUids));
128	}
129	
130	/** The units ONE attached Energy provides, on the Pokémon it is attached to —
131	    the per-card half of `providedEnergy` above, split out so the `providesEnergy`
132	    CardFilter (interpreter.ts) reads provision through the SAME code the §8.2
133	    cost matcher does. Two readers of one rule: an Energy that can pay a {L} cost
134	    is exactly an Energy a "discard a {L} Energy" effect may take, and letting
135	    those two drift would let a Kilowattrel pay {L} with a card the very same
136	    attack then refuses to discard. */
137	export function unitsProvidedBy(state: GameState, pokemon: InPlayPokemon, uid: string): string[] {
138	  return unitsOf(state, uid, specialEnergyUids(state, pokemon));
139	}
140	
141	/** Does `uid`, attached to `pokemon`, provide `energyType` (§6.3)? The
142	    `providesEnergy` filter's predicate.
143	
144	    A WILDCARD provider matches every type: Luminous Energy "provides every type
145	    of Energy but only 1 at a time", so it IS a {L} Energy for a card that asks
146	    for one — the same ANY_ENERGY unit costMet lets fill any typed slot. And
147	    because provision is read on the HOST, the answer genuinely moves with the
148	    board: that same Luminous provides only {C} once another Special Energy joins
149	    it, and stops being a {L} Energy at all. */
150	export function providesEnergyType(
151	  state: GameState,
152	  pokemon: InPlayPokemon,
153	  uid: string,
154	  energyType: string,
155	): boolean {
156	  const units = unitsProvidedBy(state, pokemon, uid);
157	  return units.includes(energyType) || units.includes(ANY_ENERGY);
158	}
