1	import { describe, expect, it } from "vitest";
2	import { applyAction, deriveAttackEffect, topUid } from "./index";
3	import type { GameEvent, GameState } from "./index";
4	import {
5	  KNOCKOUT_DECK,
6	  activeUid,
7	  attachFromDeck,
8	  benchFromDeck,
9	  benchTopUid,
10	  deepFreeze,
11	  driveSetup,
12	  must,
13	  mustApply,
14	  setActiveFromDeck,
15	  setBenchDamage,
16	  setPrizes,
17	  types,
18	} from "./testFixtures";
19	
20	// M4 slice 4 — the Knock Out generalized off the Active. Two reaches the old
21	// engine could not: BENCH Knock Outs (a spread attack finishing a Benched
22	// Pokémon, resolved by the shared board sweep in flow.ts collectKnockOuts) and
23	// MID-TURN Knock Outs that RESUME the actor's turn (evolve-below-HP — see the
24	// characterization test in stadiumTool.test.ts). This suite drives the spread
25	// path end to end; the fix-sniper's "Spread Shot" does 30 to the Active AND 20
26	// to each of the opponent's Benched Pokémon (effect text the deriver reads).
27	
28	/** Setup then open P1's turn 2 (P2 went first and passed) — P1 goes second, so
29	    turn 2 is their first turn with no §4 attack restriction. */
30	function p1Turn2(seed: number): GameState {
31	  const state = driveSetup(seed, { p1: KNOCKOUT_DECK, p2: KNOCKOUT_DECK }, { first: "p2" });
32	  return must(applyAction(state, { type: "endTurn", seat: "p2" }));
33	}
34	
35	function find<T extends GameEvent["type"]>(
36	  events: GameEvent[],
37	  type: T,
38	): Extract<GameEvent, { type: T }> | undefined {
39	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
40	}
41	
42	/** P1 fix-sniper (energied to attack) vs a P2 board — the shared arrangement.
43	    setActiveFromDeck displaces the setup Active to the bench, so p2's bench is
44	    reset to EXACTLY the requested Pokémon before they are added. */
45	function sniperVs(seed: number, p2Active: string, bench: string[]): GameState {
46	  let state = p1Turn2(seed);
47	  state = setActiveFromDeck(state, "p1", "fix-sniper");
48	  state = attachFromDeck(state, "p1", "fix-energy", 1); // pays Spread Shot [C]
49	  state = setActiveFromDeck(state, "p2", p2Active);
50	  state = { ...state, players: { ...state.players, p2: { ...state.players.p2, bench: [] } } };
51	  for (const id of bench) state = benchFromDeck(state, "p2", id);
52	  return state;
53	}
54	
55	describe("spreadDamage — the derived spread op", () => {
56	  it("derives from its effect text, with and without the era's W/R clarifier", () => {
57	    expect(
58	      deriveAttackEffect("This attack does 20 damage to each of your opponent's Benched Pokémon."),
59	    ).toEqual([{ op: "spreadDamage", target: "opponentBench", amount: 20 }]);
60	    expect(
61	      deriveAttackEffect(
62	        "This attack does 30 damage to each of your opponent's Benched Pokémon. (Don't apply Weakness and Resistance for Benched Pokémon.)",
63	      ),
64	    ).toEqual([{ op: "spreadDamage", target: "opponentBench", amount: 30 }]);
65	  });
66	});
67	
68	describe("spread attack damage (§8.5)", () => {
69	  it("places flat damage on EVERY opponent Benched Pokémon — no Weakness on the Bench", () => {
70	    // fix-weak is weak to Fire ×2, but on the Bench weakness never applies.
71	    const state = sniperVs(1, "fix-wall", ["fix-wall", "fix-weak"]);
72	    const benchedWeak = benchTopUid(state, "p2", 1);
73	    const { state: after, events } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
74	
75	    // The derived spread ran — it is SIMULATED, not flagged as skipped.
76	    expect(types(events)).not.toContain("ATTACK_EFFECT_SKIPPED");
77	    // Active took the base 30; each benched a FLAT 20 (no ×2 on fix-weak).
78	    expect(after.players.p2.active?.damage).toBe(30);
79	    expect(after.players.p2.bench[0]?.damage).toBe(20);
80	    expect(after.players.p2.bench[1]?.damage).toBe(20);
81	    const weakHit = events.find((e) => e.type === "DAMAGE_DEALT" && e.uid === benchedWeak);
82	    expect(weakHit).toMatchObject({ seat: "p2", base: 20, dealt: 20, weakness: null, resistance: null });
83	  });
84	
85	  it("still applies a benched Pokémon's own damage-reduction passive (Bouffer) to spread", () => {
86	    // A reduction passive that is NOT Active-only (Bouffalant "Bouffer", −20)
87	    // reduces spread damage on the Bench too; the attacker's Active-only bonus
88	    // (Vitality Band) does not reach the Bench.
89	    const state = sniperVs(7, "fix-wall", ["sv03-174"]); // Bouffalant benched
90	    const benchedBouff = benchTopUid(state, "p2", 0);
91	    const { state: after, events } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
92	    const hit = events.find(
93	      (e) => e.type === "DAMAGE_DEALT" && e.uid === benchedBouff,
94	    ) as Extract<GameEvent, { type: "DAMAGE_DEALT" }> | undefined;
95	    expect(hit).toMatchObject({ base: 20, reduction: 20, dealt: 0 });
96	    expect(after.players.p2.bench[0]?.damage).toBe(0); // 20 spread − 20 Bouffer
97	  });
98	
99	  it("is a no-op against an empty opponent Bench", () => {
100	    const state = sniperVs(4, "fix-wall", []);
101	    const { events } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
102	    // Only the Active took damage; nothing on the Bench, no KO, no crash.
103	    expect(events.filter((e) => e.type === "DAMAGE_DEALT")).toHaveLength(1);
104	    expect(types(events)).not.toContain("KNOCKED_OUT");
105	  });
106	});
107	
108	describe("bench Knock Outs via spread (§8.1, generalized off the Active)", () => {
109	  it("Knocks Out a Benched Pokémon the spread makes lethal — owes its prize, NO promotion", () => {
110	    let state = sniperVs(2, "fix-wall", ["fix-victim"]); // wall survives 30
111	    state = setBenchDamage(state, "p2", 0, 10); // 10 + spread 20 = 30 = fix-victim HP
112	    const benched = benchTopUid(state, "p2", 0);
113	    const { state: after, events } = mustApply(state, { type: "attack", seat: "p1", index: 0 });
114	
115	    const ko = find(events, "KNOCKED_OUT");
116	    expect(ko).toMatchObject({ seat: "p2", uid: benched });
117	    expect(ko?.discarded).toContain(benched);
118	    expect(after.players.p2.discard).toContain(benched);
119	    // A benched KO leaves no empty Active spot, so it owes a prize but NO
120	    // promotion; the bench compacts and the Active is untouched.
121	    expect(after.phase).toEqual({ kind: "ko:takePrizes", seat: "p1", count: 1 });
122	    expect(after.pending.map((s) => s.kind)).toEqual([
123	      "takePrizes",
124	      "endTurn",
125	      "checkup",
